<script setup lang="ts">const username=ref("operator"),password=ref("123456"),error=ref(""),pending=ref(false),config=useRuntimeConfig(),{setToken}=useAdminAuth();async function login(){pending.value=true;try{const r=await $fetch<any>(`${config.public.apiBase}/auth/admin/login`,{method:"POST",body:{username:username.value,password:password.value}});setToken(r.session.accessToken);await navigateTo("/")}catch(e:any){error.value=e?.data?.message||"登录失败"}finally{pending.value=false}}</script>
<template><main><section class="intro"><b>SQJ　商情据</b><p>OFFICIAL OPERATIONS</p><h1>让平台运营，<br><em>清晰、可靠、可追溯</em></h1><span>管理企业数据源、资讯审核、报告交付、API 计费、客户交易和审计日志。</span><div><i>数据源状态</i><i>内容审核</i><i>交易与交付</i><i>系统审计</i></div></section><section class="card"><p>运营人员专用</p><h2>登录官方运营后台</h2><label>运营账号<input v-model="username"></label><label>密码<input v-model="password" type="password"></label><span v-if="error">{{ error }}</span><button @click="login">{{ pending?"登录中…":"进入运营工作台 →" }}</button><small>演示账号：operator / 123456<br>用户端账号不能登录此后台。</small></section></main></template>
